const metricText = (key,v) => v===null||!Number.isFinite(v)?'—':['conversions','clicks','impressions'].includes(key) ? count(v) : key === 'roas' ? ratio(v) : key==='cpc'?costMoney(v): ['ctr','cvr'].includes(key)?`${v.toFixed(2)}%`:money(v);
