const labels=()=>({spend:'Spend',revenue:valueLabel(),conversions:capital(conversionWord()),roas:'ROAS',clicks:'Clicks',impressions:'Impressions',cpc:costLabel(),ctr:'CTR',cvr:'Recorded conversions per click'});
