 const blankDraft=isBlankReportDraft(existing);
 const replaceMessage=linked?'Replace the active dataset with this later report? Your current plan, report edits and linked investigation remain in this session. Nothing is saved automatically.':blankDraft?'Add this report to your current draft? Your written sections and plan will remain in this session. Nothing is saved automatically.':'Replace your current session dataset and discard its active plan and report edits? Saved investigations and Time Machine snapshots are not changed.';
 if((existing?.data||hasWork(existing?.plan)||hasWork(existing?.report))&&!confirm(replaceMessage))return;
